/**
 * The manifest of `thetowersdk.mcpb`, and the version a build is stamped with.
 *
 * Apart from `build-mcpb.mjs` so a test can import it: that script packs a bundle when it is run,
 * and a test that wants to read the manifest should not have to.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    MANIFEST_VERSION, PRIVACY_POLICY_URL, bundleVersion, parseAuthor, buildManifest
 * depends    —
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */

/** The newest manifest version the pinned bundle CLI validates. */
export const MANIFEST_VERSION = '0.4'

/** What the extension sends off the machine, and to whom. Shown on its page in Claude Desktop. */
export const PRIVACY_POLICY_URL = 'https://github.com/BeardedUnicorn/TheTowerSDK/blob/main/PRIVACY.md'

/**
 * The version a bundle carries.
 *
 * `package.json` only changes in the release commit, so a bundle built from any later commit said
 * it was the last release while holding tools that release never had. Only a build of the commit
 * the release tag points at is that release; every other one says which commit it is.
 */
export function bundleVersion(version, { tagsAtHead = [], shortSha } = {}) {
  if (tagsAtHead.includes(`v${version}`) || !shortSha) return version
  return `${version}-dev.${shortSha}`
}

/** `Name <email> (url)`, the form npm documents for a string `author`. */
export function parseAuthor(author) {
  if (typeof author !== 'string') return author
  const match = author.match(/^\s*([^<(]+?)\s*(?:<([^>]+)>)?\s*(?:\(([^)]+)\))?\s*$/)
  if (!match) return { name: author }
  const [, name, email, url] = match
  return { name, ...(email ? { email } : {}), ...(url ? { url } : {}) }
}

function repositoryUrl(repository) {
  const url = typeof repository === 'string' ? repository : repository?.url
  return url?.replace(/^git\+/, '').replace(/\.git$/, '')
}

/**
 * The manifest, from `package.json` and the version this build carries.
 *
 * Every setting is optional and defaults to an empty value, because the bundle library leaves an
 * unset optional `${user_config.…}` in place as literal text, which the server would then read as
 * a path. The server treats an empty value as unset.
 *
 * `TOWER_MECHANICS_MAP_DIR` is set straight from `${HOME}` rather than through the Notes Folder
 * setting's default: a setting's default is substituted after the system directories, so
 * `${HOME}` inside one would reach the server unexpanded. The setting travels as
 * `TOWER_NOTES_DIR`, which the server prefers when it is not empty.
 */
export function buildManifest(pkg, version = pkg.version) {
  return {
    manifest_version: MANIFEST_VERSION,
    name: 'thetowersdk',
    display_name: 'The Tower SDK',
    version,
    description: pkg.description,
    long_description: [
      "Game data, formulas and save-file reading for The Tower, as tools an assistant can call: look up a table, run a calculator, decode the game's tool_export.json, read the community wiki, and plan an upgrade path from a real account.",
      '',
      "On a Mac the game's export is found automatically. On Windows and Linux, point the Tool Export setting at it.",
    ].join('\n'),
    author: parseAuthor(pkg.author),
    repository: { type: 'git', url: repositoryUrl(pkg.repository) },
    homepage: pkg.homepage,
    documentation: pkg.homepage,
    support: pkg.bugs?.url,
    icon: 'icon.png',
    server: {
      type: 'node',
      entry_point: 'mcp/server.mjs',
      mcp_config: {
        command: 'node',
        args: ['${__dirname}/mcp/server.mjs'],
        env: {
          TOWER_TOOL_EXPORT: '${user_config.tool_export}',
          TOWER_MECHANICS_MAP_DIR: '${HOME}/Documents/TheTowerSDK/mechanics-map',
          TOWER_NOTES_DIR: '${user_config.notes_folder}',
          TOWER_WIKI_OFFLINE: '${user_config.wiki_offline}',
        },
      },
    },
    // The server decides its tools and prompts at start-up, so neither list is written down here.
    tools_generated: true,
    prompts_generated: true,
    keywords: pkg.keywords,
    license: pkg.license,
    privacy_policies: [PRIVACY_POLICY_URL],
    compatibility: {
      platforms: ['darwin', 'win32', 'linux'],
      runtimes: { node: pkg.engines.node },
    },
    user_config: {
      tool_export: {
        type: 'file',
        title: 'Tool Export',
        description:
          "The game's tool_export.json. On a Mac leave it empty: it is found in the game's own folder. On Windows and Linux the tools that read your account need it.",
        required: false,
        default: '',
      },
      notes_folder: {
        type: 'directory',
        title: 'Notes Folder',
        description:
          'Where the note-taking tools keep their map and ledger. Leave empty for Documents/TheTowerSDK/mechanics-map.',
        required: false,
        default: '',
      },
      wiki_offline: {
        type: 'boolean',
        title: 'Offline Wiki',
        description:
          'Never contact the community wikis. The wiki tools then answer only from pages already cached on this computer.',
        required: false,
        default: false,
      },
    },
  }
}
